use crate::types::{Color, Square};

pub const SQUARES: [Square; 64] = {
    let mut squares = [Square::new(0, 0).unwrap(); 64];
    let mut i = 0;
    while i < 64 {
        let rank = (i / 8) as u8;
        let file = (i % 8) as u8;
        squares[i] = Square::new(rank, file).unwrap();
        i += 1;
    }
    squares
};

#[inline]
pub const fn sq_occupancy_bit(sq: Square) -> u64 {
    1u64 << sq.0
}

#[inline]
pub const fn set_bit(bb: u64, sq: Square) -> u64 {
    bb | (1u64 << sq.0)
}

#[inline]
pub const fn clear_bit(bb: u64, sq: Square) -> u64 {
    bb & !(1u64 << sq.0)
}

#[inline]
pub const fn toggle_bit(bb: u64, sq: Square) -> u64 {
    bb ^ (1u64 << sq.0)
}

#[inline]
pub const fn is_bit_set(bb: u64, sq: Square) -> bool {
    (bb & (1u64 << sq.0)) != 0
}

#[inline]
pub const fn ls1bb(bb: u64) -> Square {
    // 最低位设为1的bit对应的位置
    Square((bb.trailing_zeros() as u8))
}

#[inline]
pub const fn ms1bb(bb: u64) -> Square {
    // 最高位设为1的bit对应的位置
    Square((63 - bb.leading_zeros()) as u8)
}

pub fn pop_bit(bb: &mut u64) -> Option<Square> {
    if *bb == 0 {
        return None;
    }
    let sq = ls1bb(*bb);
    *bb = clear_bit(*bb, sq);
    Some(sq)
}

