{"content":"// zobrist.rs - Zobrist 哈希和 transposition table

use crate::types::{Color, Piece, PieceType, Square};

const HASH_KEY_SIZE: usize = 480; // 64 squares * 6 piece types * 2 colors + castling + ep + side to move
const TT_SIZE: usize = 1 << 20; // 1 million entries

#[derive(Clone)]
pub struct ZobristHasher {
    random_keys: [[u64; 6]; 64], // [square][piece_type]
    side_to_move: u64,
    castling_keys: [u64; 16],
    en_passant_keys: [u64; 64],
}

impl Default for ZobristHasher {
    fn default() -> Self {
        Self::new()
    }
}

impl ZobristHasher {
    pub fn new() -> Self {
        let mut random_keys = [[[0u64; 6]; 64]];
        for square in 0..64 {
            for piece_type in 0..6 {
                random_keys[0][square][piece_type] = Self::random_u64();
            }
        }

        let side_to_move = Self::random_u64();
        let castling_keys = [0u64; 16];
        let en_passant_keys = [0u64; 64];

        ZobristHasher {
            random_keys,
            side_to_move,
            castling_keys,
            en_passant_keys,
        }
    }

    fn random_u64() -> u64 {
        use std::time::{SystemTime, UNIX_EPOCH};
        let start = SystemTime::now();
        let since_the_epoch = start.duration_since(UNIX_EPOCH).unwrap();

        let mut random_u64: u64 = since_the_epoch.as_nanos() as u64;
        random_u64 ^= random_u64 >> 33;
        random_u64 *= 0xff51afd7ed558ccd;
        random_u64 ^= random_u64 >> 33;
        random_u64 *= 0xc4ceb9fe1a85ec53;
        random_u64 ^= random_u64 >> 33;

        random_u64
    }

    pub fn hash_position(&self, board: &Board, game_state: &GameState) -> u64 {
        let mut hash = 0u64;

        for piece in 0..6 {
            for square in 0..64 {
                if board.is_piece_at(square, PieceType::from_index(piece as u8).unwrap(), Color::White) {
                    hash ^= self.random_keys[0][square][piece];
                }
                if board.is_piece_at(square, PieceType::from_index(piece as u8).unwrap(), Color::Black) {
                    hash ^= self.random_keys[0][square][piece];
                }
            }
        }

        hash ^= self.side_to_move;

        // Castling rights
        let castling_index = game_state.castling_rights.0 as usize;
        if castling_index != 0 {
            hash ^= self.castling_keys[castling_index];
        }

        // En passant target
        if let Some(ep_sq) = game_state.en_passant_target {
            hash ^= self.en_passant_keys[ep_sq.0 as usize];
        }

        hash
    }

    fn update_hash(&self, current_hash: u64, from: Square, to: Square, piece: Piece, captured: Option<Piece>) -> u64 {
        let mut hash = current_hash;

        // Remove piece from from square
        let piece_idx = piece.piece_type as usize;
        hash ^= self.random_keys[0][from.0 as usize][piece_idx];

        // Add piece to to square
        hash ^= self.random_keys[0][to.0 as usize][piece_idx];

        // If capture, remove captured piece
        if let Some(captured_piece) = captured {
            let captured_idx = captured_piece.piece_type as usize;
            hash ^= self.random_keys[0][to.0 as usize][captured_idx];
        }

        hash
    }
}

pub type TTKey = u64;
pub type TTPiece = Piece;
pub const TTSquareMask: u64 = 0xFF;

#[derive(Copy, Clone)]
pub struct TTEntry {
    key: TTKey,
    move: Move,
    depth: i32,
    score: i32,
    flag: TTFlag,
}

#[derive(Copy, Clone)]
pub enum TTFlag {
    LowerBound = 0,   // beta cut-off: score is a lower bound
    UpperBound = 1,   // alpha cut-off: score is an upper bound
    Exact = 2,        // exact score
}

pub struct TranspositionTable {
    table: Box<[TTEntry]>,
    size: usize,
}

impl TranspositionTable {
    pub fn new(size: usize) -> Self {
        let table = vec![TTEntry {
            key: 0,
            move: Move::new(Square(0), Square(0), None, Piece::new(PieceType::Pawn, Color::White)),
            depth: 0,
            score: 0,
            flag: TTFlag::Exact,
        }; size];

        TranspositionTable {
            table: table.into_boxed_slice(),
            size,
        }
    }

    pub fn get(&self, key: TTKey) -> Option<TTEntry> {
        if self.size == 0 {
            return None;
        }

        let index = key as usize % self.size;
        if self.table[index].key == key {
            Some(self.table[index])
        } else {
            None
        }
    }

    pub fn store(&mut self, key: TTKey, entry: TTEntry) {
        if self.size == 0 {
            return;
        }

        let index = key as usize % self.size;

        // Always replace if the new entry has higher depth or equal depth with exact score
        let should_replace = entry.depth > self.table[index].depth || 
            (entry.depth == self.table[index].depth && entry.flag == TTFlag::Exact);

        if should_replace {
            self.table[index] = entry;
        }
    }

    pub fn clear(&mut self) {
        for entry in &mut self.table[..] {
            entry.key = 0;
        }
    }

    pub fn set_size(&mut self, new_size: usize) {
        self.size = new_size;
    }

    pub fn size_mb(&self) -> usize {
        self.size * std::mem::size_of::<TTEntry>() / (1024 * 1024)
    }

    pub fn occupancy(&self) -> f64 {
        if self.size == 0 {
            return 0.0;
        }

        let occupied = self.table.iter().filter(|e| e.key != 0).count();
        (occupied as f64 / self.size as f64) * 100.0
    }
