#[derive(Clone)]
pub struct Board {
    // Bitboards for each piece type and color
    pub pawn_bb: [u64; 2],   // [white, black]
    pub knight_bb: [u64; 2],
    pub bishop_bb: [u64; 2],
    pub rook_bb: [u64; 2],
    pub queen_bb: [u64; 2],
    pub king_bb: [u64; 2],

    // Combined bitboards
    pub all_pieces_bb: u64,
    pub white_pieces_bb: u64,
    pub black_pieces_bb: u64,
}

impl Board {
    pub fn new() -> Self {
        let mut board = Board {
            pawn_bb: [0; 2],
            knight_bb: [0; 2],
            bishop_bb: [0; 2],
            rook_bb: [0; 2],
            queen_bb: [0; 2],
            king_bb: [0; 2],
            all_pieces_bb: 0,
            white_pieces_bb: 0,
            black_pieces_bb: 0,
        };

        board.reset_to_start();
        board
    }

    pub fn reset_to_start(&mut self) {
        // Clear all bitboards
        self.pawn_bb = [0; 2];
        self.knight_bb = [0; 2];
        self.bishop_bb = [0; 2];
        self.rook_bb = [0; 2];
        self.queen_bb = [0; 2];
        self.king_bb = [0; 2];
        self.all_pieces_bb = 0;
        self.white_pieces_bb = 0;
        self.black_pieces_bb = 0;

        // Set up white pieces (rank 1 and 2)
        let back_rank = [
            Square::new(0, 0).unwrap(), // a1
            Square::new(0, 1).unwrap(), // b1
            Square::new(0, 2).unwrap(), // c1
            Square::new(0, 3).unwrap(), // d1
            Square::new(0, 4).unwrap(), // e1
            Square::new(0, 5).unwrap(), // f1
            Square::new(0, 6).unwrap(), // g1
            Square::new(0, 7).unwrap(), // h1
        ];

        let pawn_rank = [
            Square::new(1, 0).unwrap(), // a2
            Square::new(1, 1).unwrap(), // b2
            Square::new(1, 2).unwrap(), // c2
            Square::new(1, 3).unwrap(), // d2
            Square::new(1, 4).unwrap(), // e2
            Square::new(1, 5).unwrap(), // f2
            Square::new(1, 6).unwrap(), // g2
            Square::new(1, 7).unwrap(), // h2
        ];

        for &sq in &back_rank {
            match sq.file() {
                0 => self.add_piece(Piece::new(PieceType::Rook, Color::White), sq),
                1 => self.add_piece(Piece::new(PieceType::Knight, Color::White), sq),
                2 => self.add_piece(Piece::new(PieceType::Bishop, Color::White), sq),
                3 => self.add_piece(Piece::new(PieceType::Queen, Color::White), sq),
                4 => self.add_piece(Piece::new(PieceType::King, Color::White), sq),
                5 => self.add_piece(Piece::new(PieceType::Bishop, Color::White), sq),
                6 => self.add_piece(Piece::new(PieceType::Knight, Color::White), sq),
                7 => self.add_piece(Piece::new(PieceType::Rook, Color::White), sq),
                _ => unreachable!(),
            }
        }

        for &sq in &pawn_rank {
            self.add_piece(Piece::new(PieceType::Pawn, Color::White), sq);
        }

        // Set up black pieces (rank 7 and 6)
        let back_rank = [
            Square::new(7, 0).unwrap(), // a8
            Square::new(7, 1).unwrap(), // b8
            Square::new(7, 2).unwrap(), // c8
            Square::new(7, 3).unwrap(), // d8
            Square::new(7, 4).unwrap(), // e8
            Square::new(7, 5).unwrap(), // f8
            Square::new(7, 6).unwrap(), // g8
            Square::new(7, 7).unwrap(), // h8
        ];

        let pawn_rank = [
            Square::new(6, 0).unwrap(), // a7
            Square::new(6, 1).unwrap(), // b7
            Square::new(6, 2).unwrap(), // c7
            Square::new(6, 3).unwrap(), // d7
            Square::new(6, 4).unwrap(), // e7
            Square::new(6, 5).unwrap(), // f7
            Square::new(6, 6).unwrap(), // g7
            Square::new(6, 7).unwrap(), // h7
        ];

        for &sq in &back_rank {
            match sq.file() {
                0 => self.add_piece(Piece::new(PieceType::Rook, Color::Black), sq),
                1 => self.add_piece(Piece::new(PieceType::Knight, Color::Black), sq),
                2 => self.add_piece(Piece::new(PieceType::Bishop, Color::Black), sq),
                3 => self.add_piece(Piece::new(PieceType::Queen, Color::Black), sq),
                4 => self.add_piece(Piece::new(PieceType::King, Color::Black), sq),
                5 => self.add_piece(Piece::new(PieceType::Bishop, Color::Black), sq),
                6 => self.add_piece(Piece::new(PieceType::Knight, Color::Black), sq),
                7 => self.add_piece(Piece::new(PieceType::Rook, Color::Black), sq),
                _ => unreachable!(),
            }
        }

        for &sq in &pawn_rank {
            self.add_piece(Piece::new(PieceType::Pawn, Color::Black), sq);
        }
    }

    pub fn add_piece(&mut self, piece: Piece, square: Square) {
        match piece.piece_type {
            PieceType::Pawn => self.pawn_bb[piece.color as usize] = set_bit(self.pawn_bb[piece.color as usize], square),
            PieceType::Knight => self.knight_bb[piece.color as usize] = set_bit(self.knight_bb[piece.color as usize], square),
            PieceType::Bishop => self.bishop_bb[piece.color as usize] = set_bit(self.bishop_bb[piece.color as usize], square),
            PieceType::Rook => self.rook_bb[piece.color as usize] = set_bit(self.rook_bb[piece.color as usize], square),
            PieceType::Queen => self.queen_bb[piece.color as usize] = set_bit(self.queen_bb[piece.color as usize], square),
            PieceType::King => self.king_bb[piece.color as usize] = set_bit(self.king_bb[piece.color as usize], square),
        }

        self.all_pieces_bb = set_bit(self.all_pieces_bb, square);
        if piece.color == Color::White {
            self.white_pieces_bb = set_bit(self.white_pieces_bb, square);
        } else {
            self.black_pieces_bb = set_bit(self.black_pieces_bb, square);
        }
    }

    pub fn remove_piece(&mut self, piece: Piece, square: Square) {
        match piece.piece_type {
            PieceType::Pawn => self.pawn_bb[piece.color as usize] = clear_bit(self.pawn_bb[piece.color as usize], square),
            PieceType::Knight => self.knight_bb[piece.color as usize] = clear_bit(self.knight_bb[piece.color as usize], square),
            PieceType::Bishop => self.bishop_bb[piece.color as usize] = clear_bit(self.bishop_bb[piece.color as usize], square),
