        }

        self.all_pieces_bb = clear_bit(self.all_pieces_bb, square);
        if piece.color == Color::White {
            self.white_pieces_bb = clear_bit(self.white_pieces_bb, square);
        } else {
            self.black_pieces_bb = clear_bit(self.black_pieces_bb, square);
        }
    }

