#[derive(Copy, Clone, Debug)]
pub struct GameState {
    pub side_to_move: Color,
    pub castling_rights: CastlingRights,
    pub en_passant_target: Option<Square>,
    pub halfmove_clock: u32,
    pub fullmove_number: u32,
}

impl GameState {
    pub const fn new() -> Self {
        GameState {
            side_to_move: Color::White,
            castling_rights: CastlingRights::ALL,
            en_passant_target: None,
            halfmove_clock: 0,
            fullmove_number: 1,
        }
    }

    pub const fn is_valid(&self) -> bool {
        self.side_to_move != Color::White || self.castling_rights.has_kingside_castling()
    }
}

impl Default for GameState {
    fn default() -> Self {
        Self::new()
    }
}

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub struct CastlingRights(u8);

impl CastlingRights {
    pub const WHITE_KINGSIDE: u8 = 1 << 0;
    pub const WHITE_QUEENSIDE: u8 = 1 << 1;
    pub const BLACK_KINGSIDE: u8 = 1 << 2;
    pub const BLACK_QUEENSIDE: u8 = 1 << 3;

    pub const NONE: CastlingRights = CastlingRights(0);
    pub const ALL: CastlingRights = CastlingRights(15);

    pub const fn new(value: u8) -> Self {
        CastlingRights(value)
    }

    pub const fn has_kingside_castling(self, color: Color) -> bool {
        let bit = if color == Color::White {
            Self::WHITE_KINGSIDE
        } else {
            Self::BLACK_KINGSIDE
        };
        (self.0 & bit) != 0
    }

    pub const fn has_queenside_castling(self, color: Color) -> bool {
        let bit = if color == Color::White {
            Self::WHITE_QUEENSIDE
        } else {
            Self::BLACK_QUEENSIDE
        };
        (self.0 & bit) != 0
    }

    pub const fn can_castle_kingside(self, color: Color) -> bool {
        self.has_kingside_castling(color)
    }

    pub const fn can_castle_queenside(self, color: Color) -> bool {
        self.has_queenside_castling(color)
    }

    pub const fn remove_kingside(self, color: Color) -> CastlingRights {
        let bit = if color == Color::White {
            Self::WHITE_KINGSIDE
        } else {
            Self::BLACK_KINGSIDE
        };
        CastlingRights(self.0 & !bit)
    }

    pub const fn remove_queenside(self, color: Color) -> CastlingRights {
        let bit = if color == Color::White {
            Self::WHITE_QUEENSIDE
        } else {
            Self::BLACK_QUEENSIDE
        };
        CastlingRights(self.0 & !bit)
    }

    pub const fn all_castling_rights_available(self) -> bool {
        self.0 == Self::ALL.0
    }
}

