#[derive(Copy, Clone, Debug, Eq, PartialEq, Hash)]
pub struct Square(u8);

impl Square {
    pub const fn new(rank: u8, file: u8) -> Option<Self> {
        if rank < 8 && file < 8 {
            Some(Square(rank * 8 + file))
        } else {
            None
        }
    }

    pub const fn from_xy(x: u8, y: u8) -> Option<Self> {
        if x < 8 && y < 8 {
            Some(Square(x + y * 8))
        } else {
            None
        }
    }

    pub const fn rank(self) -> u8 {
        self.0 / 8
    }

    pub const fn file(self) -> u8 {
        self.0 % 8
    }

    pub const fn x(self) -> u8 {
        self.0 % 8
    }

    pub const fn y(self) -> u8 {
        self.0 / 8
    }

    pub const fn is_white(self) -> bool {
        let file = self.file();
        let rank = self.rank();
        (file % 2) == (rank % 2)
    }

    pub fn from_char(s: &str) -> Option<Self> {
        if s.len() == 2 {
            let file = s.as_bytes()[0] as char;
            let rank = s.as_bytes()[1] as char;

            if file.is_ascii_lowercase() && rank.is_ascii_digit() {
                let file = (file as u8) - b'a';
                let rank = (rank as u8) - b'1';
                Self::new(rank, file)
            } else {
                None
            }
        } else {
            None
        }
    }

    pub fn to_alg(self) -> String {
        format!("{}{}", (b'a' + self.file()) as char, (b'1' + self.rank()) as char)
    }
}

